94	/**
95	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
96	 * so tests can assert side-effects by reading that file — the second test-assertion channel
97	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
98	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
99	 *
100	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
101	 * SYNC) so a test reads the record immediately.
102	 */
103	@Service
104	public class Audit {
105	
106	    private final Path file;
107	
108	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
109	        this.file = Path.of(path);
110	    }
111	
112	    /** Append one audit record. Tests assert the exact line(s) in the file. */
113	    public synchronized void record(String entry) {
114	        try {
115	            Path parent = file.toAbsolutePath().getParent();
116	            if (parent != null) {
117	                Files.createDirectories(parent);
118	            }
119	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
120	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
121	        } catch (IOException e) {
122	            throw new UncheckedIOException(e);
123	        }
124	    }
125	
126	    /** Truncate the audit file. */
127	    public synchronized void clear() {
128	        try {
129	            Files.deleteIfExists(file);
130	        } catch (IOException e) {
131	            throw new UncheckedIOException(e);
132	        }
133	    }
134	}
