523	import org.springframework.web.server.ResponseStatusException;
524	
525	/**
526	 * The claims on a sheet: listed per person newest first, added, edited and moved through their
527	 * statuses one at a time. Settling a claim fixes its due at the rate its person's grade has then on the claim's date, or at the
528	 * figure a statement bound it to.
529	 */
530	@Service
531	public class ClaimService {
532	
533	    private final ClaimRepository claims;
534	    private final PersonRepository people;
535	    private final SheetService sheets;
536	    private final RateService rates;
537	    private final ApplicationEventPublisher events;
538	
539	    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets,
540	            RateService rates, ApplicationEventPublisher events) {
541	        this.claims = claims;
542	        this.people = people;
543	        this.sheets = sheets;
544	        this.rates = rates;
545	        this.events = events;
546	    }
547	
548	    /** Every claim on the sheet by the person who made it, each person's newest first. */
549	    @Transactional(readOnly = true)
550	    public Map<Long, List<Claim>> bySheet(String sheetId) {
551	        return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
552	                .collect(Collectors.groupingBy(Claim::getPersonId));
553	    }
554	
555	    @Transactional(readOnly = true)
556	    public List<Claim> forPerson(String sheetId, long personId) {
557	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
558	    }
559	
560	    /** Add a claim; a date left out takes the sheet's today. Returns the person it belongs to. */
561	    @Transactional
562	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
563	        Person person = people.findByIdAndSheetId(personId, sheetId)
564	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
565	        LocalDate on = date != null ? date : sheets.today(sheetId);
566	        claims.saveAndFlush(new Claim(sheetId, personId, amount, on, note == null ? "" : note));
567	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null));
568	        return personId;
569	    }
570	
571	    /** Edit a claim's amount, date and note. Returns the person it belongs to. */
572	    @Transactional
573	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
574	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
575	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
576	        claim.setAmount(amount);
577	        claim.setDate(date != null ? date : sheets.today(sheetId));
578	        claim.setNote(note == null ? "" : note);
579	        claims.flush();
580	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
581	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
582	                claim.getDate(), claim.getNumber(), null));
583	        return claim.getPersonId();
584	    }
585	
586	    /**
587	     * Move a claim to a status; a move its status does not allow, or settling by the user who opened
588	     * the claim, is refused and changes nothing.
589	     * Returns the person it belongs to.
590	     */
591	    @Transactional
592	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
593	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
594	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
595	        if (!claim.getStatus().canBecome(next)) {
596	            throw new ResponseStatusException(HttpStatus.CONFLICT,
597	                    "A " + claim.getStatus() + " claim cannot become " + next);
598	        }
599	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
600	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
601	                    "The user who opened a claim cannot settle it");
602	        }
603	        Integer number = claim.getNumber();
604	        if (next == ClaimStatus.OPEN) {
605	            number = sheets.nextClaimNumber(sheetId);
606	            claim.setNumber(number);
607	            claim.setOpenedBy(user);
608	        } else if (next == ClaimStatus.VOID) {
609	            claim.setNumber(null);
610	        }
611	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
612	        String due = null;
613	        if (next == ClaimStatus.SETTLED) {
614	            BigDecimal fixed;
615	            if (claim.isStated()) {
616	                fixed = claim.getStatedDue();
617	            } else {
618	                BigDecimal pct = owner == null ? null : rates.table(sheetId).on(owner.getGrade(), claim.getDate());
619	                fixed = RateService.due(claim.getAmount(), pct);
620	            }
621	            claim.setSettledDue(fixed);
622	            due = fixed == null ? "n/a" : fixed.toPlainString();
623	        }
624	        claim.setStatus(next);
625	        claims.flush();
626	        String person = owner == null ? "" : owner.getName();
627	        String event = switch (next) {
628	            case OPEN -> "CLAIM_OPENED";
629	            case SETTLED -> "CLAIM_SETTLED";
630	            case VOID -> "CLAIM_VOIDED";
631	            case DRAFT -> throw new IllegalStateException();
632	        };
633	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
634	        return claim.getPersonId();
635	    }
636	}
