639	/**
640	 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a DRAFT or
641	 * OPEN claim can be voided (VOID). Only OPEN and SETTLED claims count toward what is claimed.
642	 */
643	public enum ClaimStatus {
644	    DRAFT, OPEN, SETTLED, VOID;
645	
646	    /** Whether the claim counts toward claimed, due-total and every total. */
647	    public boolean counts() {
648	        return this == OPEN || this == SETTLED;
649	    }
650	
651	    /** Whether a claim in this status may move to the given one. */
652	    public boolean canBecome(ClaimStatus next) {
653	        return switch (next) {
654	            case OPEN -> this == DRAFT;
655	            case SETTLED -> this == OPEN;
656	            case VOID -> this == DRAFT || this == OPEN;
657	            case DRAFT -> false;
658	        };
659	    }
660	}
