668	
669	/** The due figures of claims and the due-total of a person's claims. */
670	public final class Dues {
671	
672	    private Dues() {
673	    }
674	
675	    /**
676	     * A claim's due figure: once settled, the due fixed then; while bound by a statement, the figure
677	     * bound then; otherwise the amount at the rate for its person's grade in force on its date. Null
678	     * when there is none.
679	     */
680	    public static BigDecimal figure(Claim claim, String grade, RateTable rates) {
681	        if (claim.getSettledDue() != null) {
682	            return claim.getSettledDue();
683	        }
684	        return claim.isStated() ? claim.getStatedDue()
685	                : RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()));
686	    }
687	
688	    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
689	    private static boolean kept(Claim claim) {
690	        return claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
691	    }
692	
693	    /**
694	     * The sum of the due figures of the claims that count (0.00 with none). Null (n/a) when the grade has
695	     * no rate on the sheet's today, unless a claim that counts keeps a figure: then it is the sum of the
696	     * figures there are.
697	     */
698	    public static BigDecimal total(String grade, List<Claim> claims, RateTable rates) {
699	        List<Claim> counting = claims.stream().filter(c -> c.getStatus().counts()).toList();
700	        boolean shown = rates.current(grade) != null || counting.stream().anyMatch(Dues::kept);
701	        return shown ? counting.stream().map(c -> figure(c, grade, rates))
702	                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
703	    }
704	}
