1196	
1197	    private final RateRepository rates;
1198	    private final SheetService sheets;
1199	    private final ApplicationEventPublisher events;
1200	
1201	    public RateService(RateRepository rates, SheetService sheets, ApplicationEventPublisher events) {
1202	        this.rates = rates;
1203	        this.sheets = sheets;
1204	        this.events = events;
1205	    }
1206	
1207	    /** The sheet's rates by grade, each grade's earliest first (one with no from-date before all). */
1208	    @Transactional(readOnly = true)
1209	    public List<Rate> list(String sheetId) {
1210	        return rates.findBySheetId(sheetId).stream()
1211	                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate::getFromDate,
1212	                        Comparator.nullsFirst(Comparator.naturalOrder())))
1213	                .toList();
1214	    }
1215	
1216	    /** The sheet's rates with its today, to find the rate in force for a grade on any date. */
1217	    @Transactional(readOnly = true)
