1223	    @Transactional
1224	    public Rate set(String sheetId, String user, String grade, LocalDate from, BigDecimal pct) {
1225	        sheets.load(sheetId, user);
1226	        BigDecimal scaled = pct.setScale(2, RoundingMode.HALF_UP);
1227	        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from).orElse(null);
1228	        if (rate == null) {
