1250	/** Every rate on a sheet, and the sheet's today: which rate is in force for a grade on a date. */
1251	public record RateTable(List<Rate> rates, LocalDate today) {
1252	
1253	    /**
1254	     * The percent in force for the grade on the date: the rate whose from-date is the latest one on
1255	     * or before it, a rate with no from-date applying from the beginning of time; null when none does.
1256	     */
