1258	        return rates.stream()
1259	                .filter(r -> r.getGrade().equals(grade))
1260	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
1261	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
1262	                .map(Rate::getPct).orElse(null);
1263	    }
1264	
1265	    /** The percent in force for the grade on the sheet's today; null when none is. */
1266	    public BigDecimal current(String grade) {
1267	        return on(grade, today);
1268	    }
