1419	
1420	/**
1421	 * Loads a sheet by id, starting an empty one when the id was never used, and keeps the sheet's
1422	 * today. The real clock is read only to start a new sheet's today; everything else that depends
1423	 * on the date asks {@link #today(String)}.
1424	 */
1425	@Service
1426	public class SheetService {
1427	
1428	    private final SheetRepository sheets;
1429	    private final Clock clock = Clock.systemDefaultZone();
1430	
1431	    public SheetService(SheetRepository sheets) {
1432	        this.sheets = sheets;
1433	    }
1434	
1435	    public Sheet load(String id, String user) {
1436	        try {
1437	            return loadOrCreate(id, user);
1438	        } catch (DataIntegrityViolationException e) {
1439	            // Another user started the same sheet at the same moment: theirs is the one.
1440	            return sheets.findById(id).orElseThrow(() -> e);
1441	        }
1442	    }
1443	
1444	    /** The sheet's today: the date to use for every decision and default date on the sheet. */
1445	    public LocalDate today(String id) {
1446	        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
1447	    }
1448	
1449	    /**
1450	     * The next claim number on the sheet: 1 for the first, then 2, and so on. Two users taking one
1451	     * at the same moment wait on each other, so no number is given twice or skipped.
1452	     */
1453	    @Transactional
1454	    public int nextClaimNumber(String id) {
1455	        if (sheets.bumpClaimNumber(id) != 1) {
1456	            throw new IllegalStateException("No such sheet " + id);
1457	        }
1458	        return sheets.lastClaimNumber(id);
1459	    }
1460	
1461	    /** Change the sheet's today, starting the sheet if it was never loaded. */
1462	    @Transactional
1463	    public Sheet setToday(String id, String user, LocalDate today) {
1464	        Sheet sheet = load(id, user);
1465	        sheet.setToday(today);
1466	        return sheets.save(sheet);
1467	    }
1468	
1469	    private Sheet loadOrCreate(String id, String user) {
1470	        return sheets.findById(id)
1471	                .orElseGet(() -> sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock))));
1472	    }
1473	}
